files.game.js:
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const N = 20, CELL = cv.width / N;
let snake = [{x: 10, y: 10}], dir = {x: 1, y: 0}, next = {x: 1, y: 0};
let food = {x: 15, y: 10}, score = 0, dead = false;

function spawnFood() {
  do { food = {x: (Math.random() * N) | 0, y: (Math.random() * N) | 0}; }
  while (snake.some(s => s.x === food.x && s.y === food.y));
}

function step() {
  dir = next;
  const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};
  if (head.x < 0 || head.y < 0 || head.x >= N || head.y >= N ||
      snake.some(s => s.x === head.x && s.y === head.y)) { dead = true; return; }
  snake.unshift(head);
  if (head.x === food.x && head.y === food.y) { score++; spawnFood(); }
  else snake.pop();
}

function draw() {
  ctx.fillStyle = '#14161b'; ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.fillStyle = '#b8f23a';
  snake.forEach((s, i) => { ctx.globalAlpha = 1 - i / snake.length * 0.6; ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2); });
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#ff5b3d'; ctx.fillRect(food.x * CELL + 3, food.y * CELL + 3, CELL - 6, CELL - 6);
}

addEventListener('keydown', e => {
  const k = e.key;
  if (k === 'ArrowUp' && dir.y !== 1) next = {x: 0, y: -1};
  else if (k === 'ArrowDown' && dir.y !== -1) next = {x: 0, y: 1};
  else if (k === 'ArrowLeft' && dir.x !== 1) next = {x: -1, y: 0};
  else if (k === 'ArrowRight' && dir.x !== -1) next = {x: 1, y: 0};
  else return;
  e.preventDefault();
});

setInterval(() => {
  if (dead) {
    document.getElementById('score').textContent = 'Game over — score ' + score + '. Press R to restart.';
    return;
  }
  step(); draw();
  document.getElementById('score').textContent = 'Score: ' + score;
}, 120);

addEventListener('keydown', e => { if (e.key === 'r' || e.key === 'R') { snake = [{x: 10, y: 10}]; dir = {x: 1, y: 0}; next = {x: 1, y: 0}; score = 0; dead = false; spawnFood(); } });
